IF NOT EXISTS (SELECT 1 FROM dbo.Cfg_Feature WHERE CompanyID = 1108 AND FeatureKey = 'memberprofile.seed_company_member_columns') INSERT dbo.Cfg_Feature (CompanyID, FeatureKey, FeatureValue, IsEnabled, UpdatedBy, UpdatedAt) VALUES (1108, 'memberprofile.seed_company_member_columns', N'1', 1, N'14_seed (from code)', GETDATE());
-- GitHub match: GitHub MemberProfile shows PresenterId for 1103 and DOJ for 1106 (column table seeding), so the old seed rows that hide them are removed.
DELETE FROM dbo.Cfg_Feature WHERE CompanyID = 1103 AND FeatureKey = 'memberprofile.hide_presenter_column' AND UpdatedBy LIKE '%seed%';
DELETE FROM dbo.Cfg_Feature WHERE CompanyID = 1106 AND FeatureKey = 'memberprofile.hide_doj_column' AND UpdatedBy LIKE '%seed%';

-- Tell the panels to re-read: bump Cfg_Version for every company that has settings rows (Cfg_Touch inserts the row when missing).
DECLARE @touch_c int;
DECLARE touch_cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT CompanyID FROM dbo.Cfg_Feature UNION SELECT CompanyID FROM dbo.Cfg_Label;
OPEN touch_cur; FETCH NEXT FROM touch_cur INTO @touch_c;
WHILE @@FETCH_STATUS = 0 BEGIN EXEC dbo.Cfg_Touch @CompanyID = @touch_c; FETCH NEXT FROM touch_cur INTO @touch_c; END;
CLOSE touch_cur; DEALLOCATE touch_cur;